head.script:
scwin.onpageload = function() {

};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq('#wfm_exam1_mf_wfm_exam1_wq_frameModal').height() < 320;
	}		
	scwin.unitTest = function() {
		//noResult="previous"
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wfm_exam1_btn_exam4_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
